@runner.task("bench", "🐉", "Bench", "The Straggler: speedup vs workers + a kill -9 mid-job")
def bench() -> None:
    """The boss fight's harness — building it is part of the fight.

    Three runs over one multi-minute source and a 3-rendition ladder: a 1-worker
    serial baseline, 8 workers, and 8 workers with one `kill -9`'d mid-transcode.
    """
    runner.warn("bench/ is yours to build — see the 🐉 Boss fight in SPEC.md")
    print(f"   {C.DIM}make fixture SECS=600   # a multi-minute source{C.RESET}")
    print(f"   {C.DIM}make md                 # read the Arena + 'the boss falls when'{C.RESET}")


@runner.task("profile", "🔥", "Bench", "Sample the running server with py-spy (10s flamegraph)")
def profile() -> None:
    """The Definition-of-done profiling gate.

    py-spy attaches to a *running* process by PID, so start the workers, submit a
    real job, and sample while it drains — a flamegraph of an idle loop tells you
    nothing. Expect most wall-clock inside ffmpeg children py-spy cannot see; what
    it shows is the orchestration overhead, which is exactly the question.
    """
    out = runner.project_dir / "docs" / "flamegraph.svg"
    out.parent.mkdir(parents=True, exist_ok=True)
    pid = os.environ.get("PID")
    if not pid:
        runner.fail("set PID=<server pid> — py-spy samples a running process")
        print(f"   {C.DIM}e.g. `PID=$(pgrep -f transcode-pipeline) make profile`{C.RESET}")
        sys.exit(1)
    runner.step("🔥", "sampling for 10s — keep a job draining meanwhile")
    runner.uv("run", "py-spy", "record", "--duration", "10", "--pid", pid, "--output", str(out))
    runner.ok(f"wrote {out}")


register_md(runner)
register_help(runner)

if __name__ == "__main__":
    runner.entrypoint(sys.argv[1:])
